import sqlite3, os, time, json
H = os.path.expanduser('~/.hermes')
T = lambda a: time.strftime('%H:%M:%S', time.localtime(float(a))) if a else '-'
kc = sqlite3.connect('file:' + H + '/kan' + 'ban.db?mode=ro', uri=True, timeout=10)
t = 't_01a1d11934a8d0a9'
r = kc.execute('select status, priority, claim_lock from tasks where id=?', (t,)).fetchone()
print(t, r)
for k, a, p in kc.execute("select kind, created_at, payload from task_events where task_id=? and kind not in ('heartbeat','comment_delivered','model_tier','wake_episode_evidence','worker_queue_reason','dispatch_skipped') order by id desc limit 7", (t,)):
    try:
        d = json.loads(p or '{}')
    except Exception:
        d = {}
    if k == 'continued' or k == 'scheduled':
        keep = {x: d.get(x) for x in ('status', 'resume_status', 'wake_at', 'wake_check', 'check_every', 'probe_host', 'awaiting', 'reason') if d.get(x) is not None}
        if 'wake_at' in keep:
            keep['wake_at'] = T(keep['wake_at'])
        print('  ', k, T(a), json.dumps(keep, default=str)[:600])
    elif k == 'worker_result':
        print('  ', k, T(a), ' '.join(str(d.get('last_output') or '')[:600].split()))
    else:
        print('  ', k, T(a), ' '.join(str(p)[:200].split()))
wc = [x[1] for x in kc.execute('pragma table_info(task_wake_checks)')]
for x in kc.execute('select * from task_wake_checks where task_id=?', (t,)):
    d = dict(zip(wc, x))
    print('  wake_check', d.get('purpose'), 'every', d.get('every'), 'next', T(d.get('next_at')), 'last', T(d.get('last_at')), 'rc', d.get('last_rc'), '| cmd', str(d.get('cmd'))[:300])
c = kc.execute("select author, created_at, body from task_comments where task_id=? order by id desc limit 1", (t,)).fetchone()
print('  last comment', c[0], T(c[1]), ' '.join((c[2] or '')[:900].split()))
EOF

